{
  "status": "SUPPORTED",
  "task_summary": "Prepare the living room for two people to enjoy refreshments while watching television. Provide each person with their own refreshment setting nearby, and place the entertainment control where it is accessible to both people.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "REGION",
        "function": "A surface area designated to hold a complete refreshment setting for one person.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "coffee table surface",
          "side table surface",
          "desk surface",
          "console table surface",
          "any flat furniture surface"
        ],
        "required_properties": []
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "A device used to control the television.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "remote control",
          "media controller",
          "TV remote"
        ],
        "required_properties": []
      },
      {
        "id": "television",
        "entity_kind": "OBJECT",
        "function": "The display device that is the focus of the viewing activity.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "television",
          "TV screen",
          "wall-mounted display"
        ],
        "required_properties": []
      },
      {
        "id": "access_zone",
        "entity_kind": "REGION",
        "function": "A spatial region where the entertainment control is placed to be reachable by both people.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "center of the room",
          "between the two seating areas",
          "on a central table"
        ],
        "required_properties": []
      }
    ],
    "functional_relations": [
      {
        "subject_role": "refreshment_setting",
        "relation": "must be located near",
        "object_role": "television",
        "required": true
      },
      {
        "subject_role": "access_zone",
        "relation": "must be accessible to",
        "object_role": "television",
        "required": true
      },
      {
        "subject_role": "access_zone",
        "relation": "must be accessible to",
        "object_role": "refreshment_setting",
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_1",
        "operation": "Place refreshment setting on surface",
        "source_role": "refreshment_setting",
        "target_role": "refreshment_setting",
        "operation_count": 2,
        "reuse_policy": "REUSABLE_ACROSS_TARGETS"
      },
      {
        "id": "op_2",
        "operation": "Place entertainment control in accessible zone",
        "source_role": "entertainment_control",
        "target_role": "access_zone",
        "operation_count": 1,
        "reuse_policy": "DEDICATED_PER_TARGET",
        "anchor_role": "television"
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {
          "label": "coffee_table",
